import json, pathlib
from playwright.sync_api import sync_playwright

HTML = pathlib.Path("landing.html").resolve().as_uri()
OUT = pathlib.Path(".").resolve()

def font_report(page):
    return page.evaluate("""() => {
      const els = [...document.querySelectorAll('body *')];
      const out = [];
      const seen = new Set();
      for (const el of els) {
        const direct = [...el.childNodes].some(n => n.nodeType===3 && n.textContent.trim());
        if (!direct) continue;
        const cs = getComputedStyle(el);
        const tag = el.tagName.toLowerCase();
        const isHeading = /^h[1-6]$/.test(tag);
        out.push({tag, cls: el.className||'', text: el.textContent.trim().slice(0,12), ff: cs.fontFamily, heading: isHeading});
      }
      return out;
    }""")

results = {}
with sync_playwright() as p:
    b = p.chromium.launch()
    for name, w, h in [("mobile", 375, 667), ("desktop", 1280, 800)]:
        ctx = b.new_context(viewport={"width": w, "height": h})
        page = ctx.new_page()
        errors = []
        failed = []
        page.on("pageerror", lambda e: errors.append(str(e)))
        page.on("requestfailed", lambda r: failed.append(r.url))
        page.route("**://*", lambda route: route.abort() if route.request.url.startswith("http") else route.continue_())
        page.goto(HTML)
        page.wait_for_timeout(300)
        # horizontal scroll check
        hscroll = page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")
        # store name position
        logo = page.evaluate("""() => {const el=document.querySelector('.logo');const r=el.getBoundingClientRect();return {top:r.top,bottom:r.bottom,left:r.left};}""")
        # first-screen visibility of prices & button
        vis = page.evaluate("""() => {
          const res = {};
          for (const el of document.querySelectorAll('.price, .cta')) {
            const r = el.getBoundingClientRect();
            res[el.textContent.trim().slice(0,10)] = {top:r.top, bottom:r.bottom, inFirst: r.bottom<=667 && r.top>=0};
          }
          return res;
        }""")
        # main width/centering (desktop)
        mainbox = page.evaluate("""() => {const m=document.querySelector('main');const r=m.getBoundingClientRect();return {left:r.left,right:r.right,width:r.width};}""")
        page.screenshot(path=f"shot_{name}_top.png")
        page.screenshot(path=f"shot_{name}_full.png", full_page=True)
        fonts = font_report(page)
        results[name] = {"hscroll": hscroll, "logo": logo, "vis": vis, "main": mainbox,
                         "errors": errors, "failed": failed, "fonts": fonts}
        ctx.close()
    b.close()

print(json.dumps(results, ensure_ascii=False, indent=1))


