import json, pathlib
from playwright.sync_api import sync_playwright

base = pathlib.Path(__file__).parent
url = (base / "landing.html").resolve().as_uri()

FONT_JS = """
() => {
  const out = [];
  const els = document.querySelectorAll('body *');
  for (const el of els) {
    const own = Array.from(el.childNodes).some(n => n.nodeType === 3 && n.textContent.trim());
    if (!own) continue;
    const cs = getComputedStyle(el);
    out.push({tag: el.tagName, text: el.textContent.trim().slice(0, 14), ff: cs.fontFamily});
  }
  return out;
}
"""

def check(page, w, h, shot):
    page.set_viewport_size({"width": w, "height": h})
    page.goto(url)
    page.wait_for_timeout(200)
    res = {"viewport": [w, h]}
    res["h_scroll"] = page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")
    btn = page.locator(".btn").bounding_box()
    res["btn_bottom"] = btn["y"] + btn["height"]
    prices = page.locator(".price").all()
    res["price_bottoms"] = [p.bounding_box()["y"] + p.bounding_box()["height"] for p in prices]
    logo = page.locator(".logo").bounding_box()
    res["logo_bottom"] = logo["y"] + logo["height"]
    res["logo_center_off"] = abs((logo["x"] + logo["width"] / 2) - w / 2)
    main = page.locator("main").bounding_box()
    res["main"] = main
    res["main_center_diff"] = abs((w - main["width"]) / 2 - main["x"]) if w >= 700 else None
    res["fonts"] = page.evaluate(FONT_JS)
    page.screenshot(path=str(base / shot))
    return res

with sync_playwright() as p:
    b = p.chromium.launch()
    ctx = b.new_context(viewport={"width": 390, "height": 700})
    pg = ctx.new_page()
    errors = []
    pg.on("pageerror", lambda e: errors.append(str(e)))
    pg.on("requestfailed", lambda r: errors.append("req:" + r.url))
    m = check(pg, 390, 700, "shot_mobile.png")
    d = check(pg, 1440, 900, "shot_desktop.png")
    print(json.dumps({"mobile": m, "desktop": d, "errors": errors}, ensure_ascii=False, indent=1))
    pg.close(); ctx.close(); b.close()


