() => {
  const out = {errors: [], texts: []};
  const de = document.documentElement;
  out.hscroll = de.scrollWidth > de.clientWidth ? (de.scrollWidth - de.clientWidth) : 0;
  const els = document.querySelectorAll('body *');
  const seen = new Set();
  els.forEach(el => {
    // direct text nodes only
    const own = Array.from(el.childNodes).filter(n => n.nodeType === 3 && n.textContent.trim()).map(n => n.textContent.trim()).join(' ');
    if (!own) return;
    if (seen.has(el)) return;
    const cs = getComputedStyle(el);
    const r = el.getBoundingClientRect();
    out.texts.push({tag: el.tagName, text: own.slice(0, 40), ff: cs.fontFamily, top: Math.round(r.top + window.scrollY), bottom: Math.round(r.bottom + window.scrollY), left: Math.round(r.left), right: Math.round(r.right), h: Math.round(r.height), visible: r.width > 0 && r.height > 0 && cs.display !== 'none' && cs.visibility !== 'hidden'});
  });
  const main = document.querySelector('main');
  const mr = main.getBoundingClientRect();
  out.main = {width: Math.round(mr.width), left: Math.round(mr.left), right: Math.round(window.innerWidth - mr.right)};
  const logo = document.querySelector('.logo');
  const lr = logo.getBoundingClientRect();
  out.logo = {bottom: Math.round(lr.bottom), left: Math.round(lr.left)};
  const btn = document.querySelector('.book-btn');
  const br = btn.getBoundingClientRect();
  out.btn = {top: Math.round(br.top), bottom: Math.round(br.bottom), radius: getComputedStyle(btn).borderRadius};
  return out;
}
"""

with sync_playwright() as p:
    browser = p.chromium.launch()
    results = {}
