            page.on("requestfailed", lambda r: failures.append(r.url))
            errors = []
            page.on("pageerror", lambda e: errors.append(str(e)))
            await page.goto(HTML, wait_until="load")
            await page.screenshot(path=f"shot_{name}_top.png")
            await page.screenshot(path=f"shot_{name}_full.png", full_page=True)
            # horizontal scroll check
            hscroll = await page.evaluate("document.documentElement.scrollWidth > document.documentElement.clientWidth")
            # font check: every element with visible text
            fonts = await page.evaluate("""() => {
                const out = [];
                const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
                const seen = new Set();
                while (walker.nextNode()) {
