                    if (!t) continue;
                    const el = walker.currentNode.parentElement;
                    if (!el || seen.has(el)) continue;
                    seen.add(el);
                    const cs = getComputedStyle(el);
                    out.push({tag: el.tagName, cls: el.className, text: t.slice(0, 20), ff: cs.fontFamily, visible: cs.display !== 'none' && el.getBoundingClientRect().width > 0});
                }
