                const logo = document.querySelector('.logo').getBoundingClientRect();
                const cta = document.querySelector('.cta').getBoundingClientRect();
                const prices = [...document.querySelectorAll('.price')].map(e => e.getBoundingClientRect());
                const main = document.querySelector('main').getBoundingClientRect();
                return {logoBottom: logo.bottom, logoCenterX: (logo.left+logo.right)/2,
                        viewportW: document.documentElement.clientWidth,
                        ctaBottom: cta.bottom, ctaTop: cta.top,
                        priceBottoms: prices.map(r => r.bottom),
                        mainLeft: main.left, mainRight: main.right, mainWidth: main.width};
            }""")
            results[name] = {"hscroll": hscroll, "fonts": fonts, "geo": geo,
                             "extRequests": requests, "failed": failures, "errors": errors}
            await ctx.close()
        await browser.close()
        print(json.dumps(results, ensure_ascii=False, indent=1))

