import json, os, sys
from playwright.sync_api import sync_playwright

BASE = os.path.dirname(os.path.abspath(__file__))
URL = "file://" + os.path.join(BASE, "landing.html")

FONT_AUDIT = """
() => {
  const out = [];
  const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
  const seen = new Set();
  while (walker.nextNode()) {
    const t = walker.currentNode;
    if (!t.textContent.trim()) continue;
    const el = t.parentElement;
    if (!el || seen.has(el)) continue;
    seen.add(el);
    const cs = getComputedStyle(el);
    out.push({tag: el.tagName.toLowerCase(), cls: el.className || '', text: t.textContent.trim().slice(0, 18), ff: cs.fontFamily, color: cs.color, size: cs.fontSize});
  }
  return out;
}
"""

def first_font(ff):
    return ff.split(",")[0].strip().strip('"').strip("'").lower()

results = {}
with sync_playwright() as p:
    browser = p.chromium.launch()
    for name, w, h in [("mobile", 390, 700), ("desktop", 1440, 900)]:
        ctx = browser.new_context(viewport={"width": w, "height": h})
        page = ctx.new_page()
        errors, failed = [], []
        page.on("console", lambda m: errors.append(m.text) if m.type == "error" else None)
        page.on("requestfailed", lambda r: failed.append(r.url))
        page.goto(URL, wait_until="load", timeout=20000)
        page.wait_for_timeout(300)
        page.screenshot(path=os.path.join(BASE, f"shot_{name}_fold.png"))
        page.screenshot(path=os.path.join(BASE, f"shot_{name}_full.png"), full_page=True)
        audit = page.evaluate(FONT_AUDIT)
        metrics = page.evaluate("""
        () => {
          const de = document.documentElement;
          const logo = document.querySelector('.logo').getBoundingClientRect();
          const main = document.querySelector('main').getBoundingClientRect();
          const cta = document.querySelector('.cta').getBoundingClientRect();
          const prices = [...document.querySelectorAll('.price')].map(e => { const r = e.getBoundingClientRect(); return {t: e.textContent.trim(), top: r.top, bottom: r.bottom, left: r.left, right: r.right}; });
          return {
            scrollW: de.scrollWidth, clientW: de.clientWidth,
            logoBottom: logo.bottom, logoCenterX: (logo.left + logo.right) / 2,
            mainW: main.width, mainLeft: main.left, mainRight: main.right,
            ctaTop: cta.top, ctaBottom: cta.bottom,
            prices, innerW: window.innerWidth
          };
        }
        """)
        results[name] = {"audit": audit, "metrics": metrics, "consoleErrors": errors, "failedRequests": failed}
        ctx.close()
    browser.close()

for name, r in results.items():
    m = r["metrics"]
    print(f"== {name} == scrollW={m['scrollW']} clientW={m['clientW']} innerW={m['innerW']}")
    print(f"  logoBottom={m['logoBottom']:.1f} logoCenterX={m['logoCenterX']:.1f} (viewport center {m['innerW']/2})")
    print(f"  mainW={m['mainW']:.1f} mainLeft={m['mainLeft']:.1f} mainRight gap={m['innerW']-m['mainRight']:.1f}")
    print(f"  ctaTop={m['ctaTop']:.1f} ctaBottom={m['ctaBottom']:.1f}")
    for pr in m["prices"]:
        print(f"  price '{pr['t']}' top={pr['top']:.1f} bottom={pr['bottom']:.1f}")
    print("  consoleErrors:", r["consoleErrors"], "failedRequests:", r["failedRequests"])
    bad = []
    for a in r["audit"]:
        f = first_font(a["ff"])
        want = "georgia" if a["tag"] in ("h1","h2","h3","h4","h5","h6") else "arial"
        if f != want:
            bad.append(a)
    print("  font mismatches:", json.dumps(bad, ensure_ascii=False) if bad else "NONE")
    print("  text elements:", len(r["audit"]))


