import asyncio, json
from playwright.async_api import async_playwright

HTML = "file:///tmp/accept-landing-page-parallel-v1-d1d627d32b26-1-u1y66vm0/y07/landing.html"

async def run():
    async with async_playwright() as p:
        b = await p.chromium.launch()
        for name, w, h in [("mobile", 320, 568), ("desktop", 1024, 768)]:
            ctx = await b.new_context(viewport={"width": w, "height": h})
            page = await ctx.new_page()
            errors = []
            page.on("pageerror", lambda e: errors.append(str(e)))
            reqs = []
            page.on("request", lambda r: reqs.append(r.url))
            await page.goto(HTML)
            await page.screenshot(path=f"shot_{name}.png")
            # horizontal scroll check
            sw = await page.evaluate("document.documentElement.scrollWidth")
            # font check: every element with visible text
            fonts = await page.evaluate("""() => {
                const out = [];
                const walker = document.createTreeWalker(document.body, NodeFilter.SHOW_TEXT);
                const seen = new Set();
                while (walker.nextNode()) {
                    const t = walker.currentNode.textContent.trim();
                    if (!t) continue;
                    const el = walker.currentNode.parentElement;
                    if (!el || seen.has(el)) continue;
                    seen.add(el);
                    const cs = getComputedStyle(el);
                    if (cs.display === 'none' || cs.visibility === 'hidden') continue;
                    const tag = el.tagName.toLowerCase();
                    const isHeading = /^h[1-6]$/.test(tag);
                    out.push({tag, text: t.slice(0, 20), heading: isHeading,
                              ff: cs.fontFamily, size: cs.fontSize,
                              color: cs.color, bg: cs.backgroundColor});
                }
                return out;
            }""")
            # first-screen positions (mobile)
            pos = await page.evaluate("""() => {
                const r = {};
                for (const [k, sel] of [['store','.store'],['h1','h1'],['cta','.cta']]) {
                    const e = document.querySelector(sel);
                    const b = e.getBoundingClientRect();
                    r[k] = {top: b.top, bottom: b.bottom, left: b.left, height: b.height};
                }
                r.prices = [...document.querySelectorAll('.price')].map(e => {
                    const b = e.getBoundingClientRect();
                    return {t: e.textContent.trim(), top: b.top, bottom: b.bottom};
                });
                return r;
            }""")
            mainw = await page.evaluate("""() => {
                const m = document.querySelector('main').getBoundingClientRect();
                return {left: m.left, right: window.innerWidth - m.right, width: m.width};
            }""")
            print(name, "scrollWidth", sw, "errors", errors, "reqs", reqs)
            print(name, "pos", json.dumps(pos, ensure_ascii=False))
            print(name, "main", mainw)
            for f in fonts:
                print("  FONT", f)
            await ctx.close()
        await b.close()

asyncio.run(run())


